/**
 * Canned states for tests, UI and 3D development. Each is built by the state builder; the JSON
 * copies next to this file are generated by `npm run fixtures` and checked by a test.
 */
import type { GameState } from '../../types/state.js';
import { stateBuilder } from '../stateBuilder.js';

/** 3x4 tiles, 3 players. ASCII: see testing/board.ts renderAscii. */
const THREE_PLAYER_MAP = [
  ['A', 'O1', 'L', 'E'],
  ['K', 'C', 'N2', 'F'],
  ['T', 'D3', 'G', 'B1'],
];

/** Ketchup New Districts + Lobbyists map (tiles X, U, W, Y, Z, V). */
const KETCHUP_MAP = [
  ['X', 'U', 'W', 'C'],
  ['Y', 'Z', 'V', 'A'],
  ['O', 'E', 'K', 'T'],
];

/** base.md §2.6: first restaurant placement, round 1 (reverse order); p3 placed, p2 to act. */
export function setupFixture(): GameState {
  return stateBuilder({ players: 3, seed: 101 })
    .tiles(THREE_PLAYER_MAP)
    .round(0)
    .restaurant('p3', 8, 3, 'NW')
    .phase({ kind: 'setup.restaurants', round: 1, order: ['p3', 'p2', 'p1'], idx: 1, placed: ['p3'], passed: [] })
    .build();
}

/** base.md §4: round 2 Restructuring. Cards hired in round 1 are in hand; p1 has submitted. */
export function restructuringFixture(): GameState {
  const b = stateBuilder({ players: 3, seed: 102 })
    .tiles(THREE_PLAYER_MAP)
    .round(2)
    .restaurant('p1', 3, 3, 'NW')
    .restaurant('p2', 8, 3, 'NW')
    .restaurant('p3', 15, 10, 'NE')
    .card('p1', 'marketing_trainee', 'hand', 'p1-mkt')
    .card('p1', 'waitress', 'hand', 'p1-w')
    .card('p1', 'management_trainee', 'hand', 'p1-mt')
    .card('p2', 'recruiting_girl', 'hand', 'p2-rg')
    .card('p2', 'kitchen_trainee', 'hand', 'p2-kt')
    .card('p3', 'errand_boy', 'hand', 'p3-eb')
    .card('p3', 'trainer', 'hand', 'p3-tr')
    .reserve('p1', { kind: 'standard', amount: 300, ceoSlots: 4 })
    .reserve('p2', { kind: 'standard', amount: 100, ceoSlots: 2 })
    .reserve('p3', { kind: 'standard', amount: 200, ceoSlots: 3 })
    .phase({ kind: 'restructuring' });
  return b
    .secret('p1', { structureDraft: { ceo: b.ceoUid('p1'), ceoSubs: ['p1-mt', 'p1-w'], managerSubs: { 'p1-mt': ['p1-mkt'] } } })
    .build();
}

/** base.md §6: round 3 Working, p2 active in the marketing sub-step; p1 done; an eternal billboard on the map. */
export function workingFixture(): GameState {
  const b = stateBuilder({ players: 3, seed: 103 })
    .tiles(THREE_PLAYER_MAP)
    .round(3)
    .cash('p1', 30)
    .cash('p2', 15)
    .cash('p3', 5)
    .restaurant('p1', 3, 3, 'NW')
    .restaurant('p2', 8, 3, 'NW')
    .restaurant('p3', 15, 10, 'NE')
    // p1: eternal billboard from round 2 (first_billboard), waitress + pricing manager at work.
    .marketeerCampaign('marketing_trainee', 'p1-mkt', {
      owner: 'p1',
      kind: 'billboard',
      number: 11,
      goods: ['burger'],
      placement: { kind: 'board', x: 11, y: 5, w: 3, h: 2 },
      remaining: 1,
      eternal: true,
      id: 'cmp-p1-bb11',
    })
    .card('p1', 'waitress', 'work', 'p1-w')
    .card('p1', 'pricing_manager', 'work', 'p1-pm')
    .card('p1', 'kitchen_trainee', 'beach', 'p1-kt')
    .milestone('p1', 'first_billboard', 2)
    .milestone('p1', 'first_burger_marketed', 2)
    .milestone('p1', 'first_lower_prices', 3)
    // p2 (active): management trainee holding kitchen + marketing trainees; recruiter; errand boy.
    .card('p2', 'management_trainee', 'work', 'p2-mt')
    .card('p2', 'recruiting_girl', 'work', 'p2-rg')
    .card('p2', 'errand_boy', 'work', 'p2-eb')
    .card('p2', 'cart_operator', 'work', 'p2-co')
    .card('p2', 'kitchen_trainee', { under: 'p2-mt' }, 'p2-kt')
    .card('p2', 'marketing_trainee', { under: 'p2-mt' }, 'p2-mkt')
    .card('p2', 'waitress', 'beach', 'p2-w')
    .card('p2', 'trainer', 'beach', 'p2-tr')
    .milestone('p2', 'first_errand_boy', 3)
    .milestone('p2', 'first_hire_3', 2)
    .card('p3', 'errand_boy', 'work', 'p3-eb')
    .card('p3', 'trainer', 'work', 'p3-tr')
    .inventory('p1', { burger: 1 })
    .bank({ cash: 120 })
    .phase({ kind: 'working', player: 'p2', idx: 1 });
  const ceo = b.ceoUid('p2');
  return b
    .turn({
      player: 'p2',
      stage: 'marketing',
      uses: { [ceo]: 0, 'p2-rg': 0, 'p2-mkt': 1, 'p2-kt': 1, 'p2-eb': 1, 'p2-co': 1 },
      hired: ['p2-w', 'p2-tr'],
      used: [ceo, 'p2-rg'],
    })
    .build();
}

