/**
 * Ketchup board entities for 3D/UI work: apartments, printed garden (tile W), parks (tile Z and a
 * placed one), coffee shops, an under-construction lobbyist road with roadworks, a freeway, the
 * rural area with a giant billboard, a gourmet guide, and Ketchup goods in stock.
 */
export function ketchupFixture(): GameState {
  const b = stateBuilder({ players: 3, seed: 105 })
    .modules([
      'ketchup:newDistricts',
      'ketchup:lobbyists',
      'ketchup:coffee',
      'ketchup:kimchi',
      'ketchup:sushi',
      'ketchup:ruralMarketeers',
      'ketchup:gourmetCritics',
    ])
    .tiles(KETCHUP_MAP)
    .round(5)
    .cash('p1', 80)
    .cash('p2', 55)
    .cash('p3', 32)
    .restaurant('p1', 12, 0, 'SE')
    .restaurant('p2', 18, 10, 'NW')
    .restaurant('p3', 10, 13, 'NW')
    .entity({ kind: 'coffeeShop', id: 'ent-cs-p1', owner: 'p1', x: 16, y: 3 })
    .entity({ kind: 'coffeeShop', id: 'ent-cs-p3', owner: 'p3', x: 0, y: 13 })
    .entity({
      kind: 'park',
      id: 'ent-park-1',
      x: 3,
      y: 13,
      w: 3,
      h: 2,
      printed: false,
      // An L park tile (questions.md Q-K1), mirrored side up.
      cells: [
        { x: 3, y: 13 },
        { x: 4, y: 13 },
        { x: 5, y: 13 },
        { x: 3, y: 14 },
      ],
    })
    .entity({
      kind: 'lobbyistRoad',
      id: 'ent-road-1',
      owner: 'p2',
      cells: [
        { x: 3, y: 10 },
        { x: 4, y: 10 },
      ],
      underConstruction: true,
      arrows: [
        { from: { x: 3, y: 10 }, dir: 'W' },
        { from: { x: 4, y: 10 }, dir: 'E' },
      ],
    })
    .entity({ kind: 'roadworks', id: 'ent-rw-1', x: 2, y: 10, road: 'ent-road-1' })
    .entity({ kind: 'roadworks', id: 'ent-rw-2', x: 5, y: 10, road: 'ent-road-1' })
    .ruralArea();
  b.entity({ kind: 'freeway', id: 'ent-fw-1', owner: 'p3', side: 'E', offset: 7, tile: b.tileId(1, 3) });
  b.marketeerCampaign('ketchup:rural_marketeer', 'p3-rm', {
    owner: 'p3',
    kind: 'giantBillboard',
    number: 21,
    goods: ['burger'],
    placement: { kind: 'rural', side: 'N' },
    remaining: 1,
    eternal: true,
    id: 'cmp-p3-gb',
  })
    .marketeerCampaign('ketchup:gourmet_food_critic', 'p1-gc', {
      owner: 'p1',
      kind: 'gourmetGuide',
      number: 17,
      goods: ['pizza'],
      placement: { kind: 'offBoard' },
      remaining: 2,
      id: 'cmp-p1-gg17',
    })
    .demand(1000, ['burger', 'burger', 'burger', 'burger'], 'p3', 'cmp-p3-gb')
    .demand(3.14, ['soft_drink', 'soft_drink'], 'p2', null)
    .demand(25, ['pizza', 'lemonade'], 'p1', 'cmp-p1-gg17')
    .card('p1', 'ketchup:lead_barista', 'work', 'p1-lb')
    .card('p1', 'waitress', 'work', 'p1-w')
    .card('p2', 'ketchup:lobbyist', 'work', 'p2-lob')
    .card('p2', 'ketchup:kimchi_master', 'work', 'p2-km')
    .card('p3', 'ketchup:sushi_cook', 'work', 'p3-sc')
    .card('p3', 'burger_cook', 'work', 'p3-bc')
    .inventory('p1', { coffee: 5, pizza: 2, lemonade: 1 })
    .inventory('p2', { kimchi: 1, soft_drink: 4 })
    .inventory('p3', { burger: 6, sushi: 2 });
  return b.phase({ kind: 'dinnertime', houses: b.houseOrder(), idx: 0 }).build();
}

export const FIXTURES = {
  setup: setupFixture,
  restructuring: restructuringFixture,
  working: workingFixture,
  dinnertime: dinnertimeFixture,
  ketchup: ketchupFixture,
} as const satisfies Record<string, () => GameState>;

export type FixtureName = keyof typeof FIXTURES;
